const flags = $json.data || $input.all().map(i => i.json);
const flat = Array.isArray(flags) ? flags : [flags];
const intake = $('Normalize Screening Intake').item.json;
const hasPermanent = flat.some(f => f.merge_branch === 'permanent' || f.is_permanent);
const maxTempDays = flat.reduce((max, f) => Math.max(max, Number(f.deferral_days) > 0 ? Number(f.deferral_days) : 0), 0);
const screeningDate = new Date(intake.screening_date);
const deferralEnd = new Date(screeningDate.getTime() + maxTempDays * 86400000);
let deferral_status;
if (hasPermanent) { deferral_status = 'Permanent'; }
else if (deferralEnd > new Date()) { deferral_status = 'Hold'; }
else { deferral_status = 'Eligible'; }
return { json: { donor_id: intake.donor_id, component_id: intake.component_id, donation_type: intake.donation_type, screening_date: intake.screening_date, max_temporary_deferral_days: maxTempDays, deferral_end_date: deferralEnd.toISOString(), deferral_status, flag_detail: flat.map(f => f.result_summary || f.flag_type).join('; ') } };
